const TYPE_CASERNE = TYPES.findIndex(t => t.nom === 'Caserne');

/* La Tour sombre du document historique reste un bâtiment distinct du Donjon.
   On en conserve ici la définition cellulaire exacte avant que le type
   d'origine soit renommé en Donjon par la bibliothèque V18. */
{
  const source = TYPES.find(t => t.nom === 'Tour sombre');
  if(source) TYPES.push(Object.assign({}, source, {
    nom:'Tour sombre',
    parts:source.parts.map(part => Object.assign({}, part))
  }));
}

/* ============================================================
   v18 — bibliothèque complète de bâtiments spéciaux
   ============================================================
   Chaque bâtiment conserve la logique cellulaire du moteur. Les gros ateliers
   occupent trois zones au sol : corps principal, cour/activité, aile secondaire.
   Les cultures et le puits restent volontairement compacts. `v18` identifie
   l'architecture et le décor : on ne réutilise pas un même modèle maquillé. */
const marquerV18=(ancien, nouveau, id)=>{
  const t=TYPES.find(q=>q.nom===ancien); if(!t) return;
  t.nom=nouveau; t.v18=id;
};
marquerV18('Forge','Forge','forge');
