function type3(nom,id,mur,toit,opt={}){
  /* v44 — deux drapeaux nouveaux, portés par le rempart :
       fusionne  : le type a le droit d'être posé CONTRE un exemplaire de
                   lui-même. Sans ça, deux remparts voisins étaient refusés,
                   et l'enceinte ne pouvait pas se former.
       orientable: la rotation du joueur est respectée telle quelle, sans que
                   le jeu cherche « la meilleure » à sa place. */
  const p0={faces:['ouvert','mur','deco','mur'],pignon:opt.pignon!==false,pente:opt.pente||1.08};
  if(opt.rond){p0.rond=true;delete p0.pignon;}
  if(opt.chaume)p0.chaume=true;
  if(opt.fortifie)p0.fortifie=true;
  const cour={df:0,cour:true,sommet:true,faces:['deco','deco','mur','deco']};
  if(opt.cloture)cour.cloture=true;
  if(opt.pergola)cour.pergola=true;
  const aile={df:1,sommet:true,pignon:opt.aileRonde?false:true,pente:opt.pente2||0.82,
              mur:opt.mur2||mur,toit:opt.toit2||toit,faces:['deco','mur','mur','mur']};
  if(opt.aileRonde){aile.rond=true;aile.cone=true;aile.haut=opt.haut||0.55;delete aile.pignon;}
  if(opt.chaume2)aile.chaume=true;
  if(opt.galerie)aile.galerie=true;
  if(opt.hourd)aile.hourd=true;
  const t={nom,id,mur,toit,v18:id,parts:[p0,cour,aile]};
  if(opt.bordEau)t.bordEau=true;
  if(opt.fusionne)t.fusionne=true;
  if(opt.orientable)t.orientable=true;
  return t;
}
function type1(nom,id,mur,toit,champ){
  return {
    nom,mur,toit,v18:id,auSol:true,parts:[{cour:true,champ,sommet:true,faces:['mur','mur','mur','mur']}]};
}

