        for(let k=0;k<2;k++)
          boiteOr(q[0],q[2],f[0],f[1],.180-k*.010,.180-k*.010,y+k*.042,y+(k+1)*.042,usure('#8d5039',k*7,.16));
        // fût en assises circulaires décroissantes : profil de bouteille
        const NL=11, HB=.84;
        for(let k=0;k<NL;k++){
          const t0=k/NL, t1=(k+1)/NL;
          const prof=(t)=>.150*(1-.10*t) * (t<.62 ? 1 : 1-(t-.62)/.38*.55);
          cylV19(q[0],q[2],prof(t0),y+.084+HB*t0,y+.084+HB*t1+.004,
                 usure(k%2?'#9a5a3f':'#8d5039',k*5,.18),13,prof(t1));
        }
