        chariot(.30,-.02,.7,'#7b5c3f');
        sacks(-.02,-.04,4,'#c2bba6');
        for(let k=0;k<6;k++){
          const q=P(-.42+rnd(k*13)*.20,-.36+rnd(k*17)*.20,y);
          ellV19(q[0],y+.010,q[2],.028,.005,.024,usure('#c9c2ae',k*5,.16),7,2);
        }
