              const t=(k+.5)/n, q=P(a0+dx*t,b0+db*t,y);
              boiteOr(q[0]+jit(k0+k*3+r2,.004),q[2]+jit(k0+k*5+r2,.004),dW[0],dW[1],L/(2*n)-.003,ep,yy0,yy1+.002,
                      usure(['#9d9486','#a9a092','#8f877a','#b2a899'][(k+r2)%4],k0+k*7+r2*3,.18));
