          etal(-.26,-.16,'a',.110,.052,TOILE1,VERTM,600,'poteries');
          etal( .10,-.14,'a',.105,.050,TOILE1,'#6b4a7a',700,'epices');
          etal(-.14, .18,'a',.115,.052,TOILE1,ROUGEM,800,'tissus');
