          const q2=P(.34,.06,y);
          for(const sg of[-1,1]) poutre([q2[0]+f[0]*sg*.046,y,q2[2]+f[1]*sg*.046],[q2[0],y+.044,q2[2]],.009,usure(ECORCE,sg*7,.14));
          poutre(P(.34,-.02,y+.086),P(.34,.14,y+.086),.046,usure('#7a5f42',5,.18));
          for(const t of[.28,.74]) ellV19(P(.34,-.02+.16*t,y)[0],y+.086,P(.34,-.02+.16*t,y)[2],.024,.048,.048,usure('#57534e',Math.round(t*40),.12),9,4);
          // 3 : panier tressé avec coussin
