          for(let k=0;k<6;k++)
            ellV19(q[0]+jit(k*13,.075),y+.048+rnd(k*7)*.036,q[2]+jit(k*17,.065),.060,.036,.054,usure([MINERAI,'#a08a52','#7d6a44'][k%3],k*9,.20),9,4);
