          for(const sa of[-1,1]) for(const sb of[-1,1])
            poutre([tq[0]+f[0]*sa*.096+s[0]*sb*.050,y,tq[2]+f[1]*sa*.096+s[1]*sb*.050],
                   [tq[0]+f[0]*sa*.096+s[0]*sb*.050,y+.150,tq[2]+f[1]*sa*.096+s[1]*sb*.050],.010,usure(BOIS6F,sa*5+sb*3,.14));
