          const pts2=[[.18,-.14,y+.384],[.22,-.14,y+.392],[.26,-.16,y+.360],[.28,-.18,y+.300],[.29,-.20,y+.250]];
          for(let k=0;k<pts2.length-1;k++){
            const A=P(pts2[k][0],pts2[k][1],pts2[k][2]), B=P(pts2[k+1][0],pts2[k+1][1],pts2[k+1][2]);
            poutre(A,B,.009,usure('#b57a45',k*7,.14));
          }
          const cq=P(.30,-.22,y);
          cylV19(cq[0],cq[2],.040,y+.090,y+.200,usure('#7d766c',7,.14),11,.036);
