          terre(-.46,.46,-.42,.44,'#8a8068');
          paves(-.30,.30,-.28,.30,['#a49a8d','#aea495','#9a9184'],.016);
          const a0=-.28,a1=.24,b0=-.22,b1=.20, eave=y+.52;
