            poutre([q[0]+s[0]*.090,y,q[2]+s[1]*.090],[q[0]+s[0]*.070,y+.34,q[2]+s[1]*.070],.009,usure('#7a5f42',11,.16));
            const t2=[q[0]+s[0]*.070,q[2]+s[1]*.070];
