            for(let j=0;j<2;j++)
              ellV19(q[0]+jit(k*13+j,.036),y+.116,q[2]+jit(k*17+j,.018),.028,.016,.024,usure([CHAUME8,'#d9bf72'][j],k*5+j,.18),7,3);
